-- Name: mark_group_messages_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_group_messages_read(p_chat_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_me uuid := auth.uid();
BEGIN
    IF v_me IS NULL THEN
        RAISE EXCEPTION 'Not authorized';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM public.chats c
        JOIN public.group_members gm
          ON gm.group_id = c.reference_id
        WHERE c.id = p_chat_id
          AND c.type = 'group'
          AND gm.user_id = v_me
          AND gm.status = 'active'
    ) THEN
        RAISE EXCEPTION 'Not a group participant';
    END IF;
    INSERT INTO public.message_reads (message_id, user_id, read_at)
    SELECT m.id, v_me, now()
    FROM public.messages m
    WHERE m.chat_id = p_chat_id
      AND m.sender_id <> v_me
      AND m.recipient_id IS NULL
    ON CONFLICT (message_id, user_id) DO NOTHING;
END;
$$;


