-- Name: messages message_cap_trigger; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER message_cap_trigger AFTER INSERT ON public.messages FOR EACH ROW EXECUTE FUNCTION public.enforce_message_cap();


